const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const ticketId = String(payload.ticketId || payload.id || `TICK-${Math.floor(100000 + Math.random() * 900000)}`).trim();
const clientId = String(payload.clientId || payload.client_id || 'unassigned-client').trim();
const clientName = String(payload.clientName || payload.name || 'Valued Client').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const subject = String(payload.subject || 'Support Request').trim();
const description = String(payload.description || payload.message || '').trim();
const category = String(payload.category || 'general').trim().toLowerCase();
const environment = String(payload.environment || 'production').trim().toLowerCase();
const reportedImpact = String(payload.reportedImpact || payload.impact || 'medium').trim().toLowerCase();

const textCorpus = `${subject} ${description}`.toLowerCase();
const criticalRegex = /\b(outage|downtime|down|crashed|breach|exploit|data loss|payment failure|cannot login|offline|sev1|p0|blocker)\b/;
const isCriticalMatch = criticalRegex.test(textCorpus);

let priority = 'P3_MEDIUM';
let slaMinutes = 720;
let assignee = 'Operations Support Lead';
let escalationChannel = '#support-queue';

if ((environment === 'production' && isCriticalMatch) || reportedImpact === 'critical' || category === 'outage' || category === 'security') {
  priority = 'P1_CRITICAL';
  slaMinutes = 60;
  assignee = 'Vikash Saravanan (Lead System Engineer) & Core SRE On-Call';
  escalationChannel = '#sre-critical-incidents';
} else if (environment === 'production' || reportedImpact === 'high' || category === 'api_failure' || isCriticalMatch) {
  priority = 'P2_HIGH';
  slaMinutes = 240;
  assignee = 'Senior Platform Engineer';
  escalationChannel = '#engineering-escalations';
} else if (category === 'billing' || reportedImpact === 'medium') {
  priority = 'P3_MEDIUM';
  slaMinutes = 720;
  assignee = 'Operations Support Lead';
  escalationChannel = '#support-queue';
} else {
  priority = 'P4_LOW';
  slaMinutes = 1440;
  assignee = 'Product Experience Team';
  escalationChannel = '#customer-feedback';
}

const now = Date.now();
const slaTargetTimestamp = new Date(now + slaMinutes * 60 * 1000).toISOString();
const isEmergency = priority === 'P1_CRITICAL';

const ticket = {
  ticketId,
  clientId,
  clientName,
  clientEmail,
  subject,
  description,
  category,
  environment,
  priority,
  slaMinutes,
  slaTargetTimestamp,
  assignee,
  escalationChannel,
  isEmergency,
  routedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    ticket,
    isEmergency
  }
}];

const item = $input.first().json;
const t = item.ticket;

const emergencyDispatch = {
  incidentRoomPath: `/ops/incidents/${t.ticketId}`,
  pagerDutyAlertTriggered: true,
  severity: 'CRITICAL_P1',
  alertMessage: `🚨 EMERGENCY P1 INCIDENT [${t.ticketId}]: ${t.subject} for ${t.clientName}. SLA Target: 60 minutes.`,
  onCallLead: t.assignee,
  broadcastChannel: t.escalationChannel,
  immediateClientNotification: {
    recipientEmail: t.clientEmail,
    subject: `[EMERGENCY P1 ACKNOWLEDGED] ${t.subject} (${t.ticketId})`,
    messageBody: `Your critical incident has engaged our Lead System Engineering team. Target resolution triage window is within 60 minutes. War room: /ops/incidents/${t.ticketId}`
  }
};

return [{
  json: {
    eventId: item.eventId,
    status: 'ticket_escalated_critical',
    detail: {
      ticket: t,
      emergencyDispatch,
      timestamp: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const t = item.ticket;

const routingDispatch = {
  portalPath: `/client/support/tickets/${t.ticketId}`,
  severity: t.priority,
  assignedTeam: t.assignee,
  slaTarget: `${t.slaMinutes} minutes (${t.slaTargetTimestamp})`,
  queueChannel: t.escalationChannel,
  clientConfirmation: {
    recipientEmail: t.clientEmail,
    subject: `[Ticket ${t.ticketId}] Received: ${t.subject}`,
    statusUrl: `/client/support/tickets/${t.ticketId}`,
    expectedResponseHours: Math.round(t.slaMinutes / 60)
  }
};

return [{
  json: {
    eventId: item.eventId,
    status: 'ticket_routed',
    detail: {
      ticket: t,
      routingDispatch,
      timestamp: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
